using System.Globalization;using JobOrbit.Application.DTOs.HiringManagerReports;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;
public sealed class HiringManagerReportRepository(JobOrbitDbContext db):IHiringManagerReportRepository
{
 public async Task<HiringManagerReportDataDto?>GetAsync(int userId,HiringManagerReportFilter f,CancellationToken t=default){var scope=await db.HiringManagerProfiles.AsNoTracking().Where(x=>x.UserId==userId&&x.User.IsActive).Select(x=>new{x.OrganizationId,x.DepartmentId}).SingleOrDefaultAsync(t);if(scope is null)return new();var jobs=db.JobPostings.AsNoTracking().Where(x=>x.OrganizationId==scope.OrganizationId&&(!scope.DepartmentId.HasValue||x.DepartmentId==scope.DepartmentId));if(f.JobId.HasValue&&!await jobs.AnyAsync(x=>x.Id==f.JobId,t))return null;if(f.JobId.HasValue)jobs=jobs.Where(x=>x.Id==f.JobId);var apps=db.JobApplications.AsNoTracking().Where(x=>jobs.Select(j=>j.Id).Contains(x.JobPostingId)&&x.AppliedAt>=f.From&&x.AppliedAt<=f.To);var evaluations=db.CandidateEvaluations.AsNoTracking().Where(x=>x.EvaluatorUserId!=null&&apps.Select(a=>a.Id).Contains(x.JobApplicationId)&&x.CreatedAt>=f.From&&x.CreatedAt<=f.To);var interviews=db.Interviews.AsNoTracking().Where(x=>apps.Select(a=>a.Id).Contains(x.JobApplicationId)&&x.ScheduledAt>=f.From&&x.ScheduledAt<=f.To&&x.Status==InterviewStatus.Completed);var decisions=db.ApplicationHiringDecisions.AsNoTracking().Where(x=>apps.Select(a=>a.Id).Contains(x.JobApplicationId)&&x.DecidedAt>=f.From&&x.DecidedAt<=f.To);
 var reviewed=await apps.CountAsync(x=>x.Status!=ApplicationStatus.Submitted&&x.Status!=ApplicationStatus.UnderReview,t);var evalCount=await evaluations.CountAsync(t);var interviewCount=await interviews.Select(x=>x.JobApplicationId).Distinct().CountAsync(t);var hired=await decisions.CountAsync(x=>x.Decision==ManagerHiringDecision.Hire,t);var rejected=await decisions.CountAsync(x=>x.Decision==ManagerHiringDecision.Reject,t);var held=await decisions.CountAsync(x=>x.Decision==ManagerHiringDecision.Hold,t);var avgScore=evalCount==0?0:await evaluations.AverageAsync(x=>x.OverallScore,t);var finalRows=await decisions.Where(x=>x.Decision==ManagerHiringDecision.Hire||x.Decision==ManagerHiringDecision.Reject).Select(x=>new{x.DecidedAt,x.JobApplication.AppliedAt}).ToListAsync(t);var avgDays=finalRows.Count==0?0:(decimal)finalRows.Average(x=>(x.DecidedAt-x.AppliedAt).TotalDays);
 var appGroups=await apps.GroupBy(x=>new{x.AppliedAt.Year,x.AppliedAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Reviewed=g.Count(x=>x.Status!=ApplicationStatus.Submitted&&x.Status!=ApplicationStatus.UnderReview)}).ToListAsync(t);var evalGroups=await evaluations.GroupBy(x=>new{x.CreatedAt.Year,x.CreatedAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Count=g.Select(x=>x.JobApplicationId).Distinct().Count()}).ToListAsync(t);var intGroups=await interviews.GroupBy(x=>new{x.ScheduledAt.Year,x.ScheduledAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Count=g.Select(x=>x.JobApplicationId).Distinct().Count()}).ToListAsync(t);var decGroups=await decisions.GroupBy(x=>new{x.DecidedAt.Year,x.DecidedAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Hired=g.Count(x=>x.Decision==ManagerHiringDecision.Hire),Rejected=g.Count(x=>x.Decision==ManagerHiringDecision.Reject)}).ToListAsync(t);var trends=new List<HiringManagerReportTrendDto>();for(var m=new DateTime(f.From.Year,f.From.Month,1,0,0,0,DateTimeKind.Utc);m<=f.To;m=m.AddMonths(1)){var a=appGroups.FirstOrDefault(x=>x.Year==m.Year&&x.Month==m.Month);var e=evalGroups.FirstOrDefault(x=>x.Year==m.Year&&x.Month==m.Month);var i=intGroups.FirstOrDefault(x=>x.Year==m.Year&&x.Month==m.Month);var d=decGroups.FirstOrDefault(x=>x.Year==m.Year&&x.Month==m.Month);trends.Add(new(){Period=m.ToString("yyyy-MM",CultureInfo.InvariantCulture),Label=m.ToString("MMM",CultureInfo.InvariantCulture),Reviewed=a?.Reviewed??0,Evaluated=e?.Count??0,Interviewed=i?.Count??0,Hired=d?.Hired??0,Rejected=d?.Rejected??0});}
 var shortlisted=await apps.CountAsync(x=>x.Status==ApplicationStatus.Shortlisted||x.Status==ApplicationStatus.Interviewing,t);var evaluatedApps=await evaluations.Select(x=>x.JobApplicationId).Distinct().CountAsync(t);var pending=await apps.CountAsync(x=>x.CandidateEvaluations.Any(e=>e.EvaluatorUserId!=null)&&x.HiringDecision==null,t);var jobRows=await jobs.Select(j=>new{j.Id,j.Title,Reviewed=j.JobApplications.Count(a=>a.AppliedAt>=f.From&&a.AppliedAt<=f.To&&a.Status!=ApplicationStatus.Submitted&&a.Status!=ApplicationStatus.UnderReview),Evaluations=j.JobApplications.SelectMany(a=>a.CandidateEvaluations).Count(e=>e.EvaluatorUserId!=null&&e.CreatedAt>=f.From&&e.CreatedAt<=f.To),Interviews=j.JobApplications.SelectMany(a=>a.Interviews).Count(i=>i.Status==InterviewStatus.Completed&&i.ScheduledAt>=f.From&&i.ScheduledAt<=f.To),Hired=j.JobApplications.Count(a=>a.HiringDecision!=null&&a.HiringDecision.Decision==ManagerHiringDecision.Hire&&a.HiringDecision.DecidedAt>=f.From&&a.HiringDecision.DecidedAt<=f.To),Rejected=j.JobApplications.Count(a=>a.HiringDecision!=null&&a.HiringDecision.Decision==ManagerHiringDecision.Reject&&a.HiringDecision.DecidedAt>=f.From&&a.HiringDecision.DecidedAt<=f.To),Average=j.JobApplications.SelectMany(a=>a.CandidateEvaluations).Where(e=>e.EvaluatorUserId!=null&&e.CreatedAt>=f.From&&e.CreatedAt<=f.To).Select(e=>(decimal?)e.OverallScore).Average()??0}).OrderByDescending(x=>x.Reviewed).Take(10).ToListAsync(t);
 return new(){Summary=new(){TotalCandidatesReviewed=reviewed,CompletedEvaluations=evalCount,InterviewsCompleted=interviewCount,HiredCandidates=hired,RejectedCandidates=rejected,HeldCandidates=held,AverageEvaluationScore=Math.Round(avgScore,2),AverageTimeToDecisionDays=Math.Round(avgDays,2)},Trends=trends,Funnel=[new(){Stage="Shortlisted",Count=shortlisted},new(){Stage="Interviewed",Count=interviewCount},new(){Stage="Evaluated",Count=evaluatedApps},new(){Stage="Held",Count=held},new(){Stage="Hired",Count=hired},new(){Stage="Rejected",Count=rejected}],JobPerformance=jobRows.Select(x=>new HiringManagerJobPerformanceDto{JobId=x.Id,JobTitle=x.Title,ApplicationsReviewed=x.Reviewed,EvaluationsCompleted=x.Evaluations,InterviewsCompleted=x.Interviews,HiredCount=x.Hired,RejectedCount=x.Rejected,AverageEvaluationScore=Math.Round(x.Average,2),HireRate=x.Reviewed==0?0:Math.Round(x.Hired*100m/x.Reviewed,2)}).ToList(),DecisionOutcomes=new(){Hire=hired,Reject=rejected,Hold=held,Pending=pending}};}
}
